<script>
  import { delay } from '@splendidlabz/utils'
  import { onMount } from 'svelte'
  import { init } from '../../../utils'
  import Icon from '../../Icon/Icon.svelte'

  let {
    show = $bindable(false),
    ref = $bindable(null),
    componentName = 'ModalTrigger',
    class: klass = '',
    icon = 'tabler:menu',
    iconClass,
    target,
    children,
    onclick = null,
    ontoggle = null,
    ...rest
  } = $props()

  let dialog = $state(null)

  init(() => {
    if (!target)
      throw new Error(`${componentName} must contain a target property`)
  })

  onMount(async _ => {
    await delay(0) // Gives time for modal to mount
    if (show) handleClick()
  })

  // ========================================
  // Event Listeners
  // ========================================
  function handleClick(event) {
    if (!dialog) dialog = document.querySelector(`#${target}`)
    dialog.showModal()
    if (onclick) onclick(event)
  }

  // Allows trigger to know whether the modal is open or closed
  function handleToggle(event) {
    const { newState } = event.detail
    if (newState === 'open') show = true
    if (newState === 'closed') show = false
    if (ontoggle) ontoggle(event)
  }
</script>

<button
  {...rest}
  bind:this={ref}
  class="button {klass}"
  aria-haspopup="dialog"
  data-modal-trigger={target}
  data-show={show}
  onclick={handleClick}
  ontoggle={handleToggle}
>
  {#if children}
    {@render children()}
  {:else if icon}
    <Icon class={iconClass} {icon} />
  {/if}
</button>
